/* ─── Color utilities (used by Sigvard lamps + now-line) ─── */
// Parse "#RRGGBB" → [r,g,b]. Returns null for invalid input.
function hexToRgb(hex){
  if(typeof hex!=="string") return null;
  // Accept rgb(r,g,b) too, so shade() can be chained on already-shaded values.
  const rgbm=hex.match(/^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/i);
  if(rgbm) return [parseInt(rgbm[1]),parseInt(rgbm[2]),parseInt(rgbm[3])];
  const h=hex.replace("#","").trim();
  if(h.length!==6) return null;
  const r=parseInt(h.slice(0,2),16),g=parseInt(h.slice(2,4),16),b=parseInt(h.slice(4,6),16);
  if(isNaN(r)||isNaN(g)||isNaN(b)) return null;
  return[r,g,b];
}
// Mix color toward white (amt>0) or black (amt<0). amt in [-1, +1].
function shade(hex,amt){
  const rgb=hexToRgb(hex); if(!rgb) return hex;
  const target=amt>=0?255:0, t=Math.abs(amt);
  const[r,g,b]=rgb.map(c=>Math.round(c+(target-c)*t));
  return`rgb(${r},${g},${b})`;
}
// Same as shade() but returns a #RRGGBB hex — use when the result needs an
// alpha suffix (e.g. `${c}55`) or further hex-based processing.
function shadeHex(hex,amt){
  const rgb=hexToRgb(hex); if(!rgb) return hex;
  const target=amt>=0?255:0, t=Math.abs(amt);
  const[r,g,b]=rgb.map(c=>Math.round(c+(target-c)*t));
  return"#"+[r,g,b].map(c=>c.toString(16).padStart(2,"0")).join("");
}
// Hex with alpha suffix — for shadow/border tints. alpha in [0,1].
function withAlpha(hex,alpha){
  const a=Math.max(0,Math.min(1,alpha));
  const hh=Math.round(a*255).toString(16).padStart(2,"0").toUpperCase();
  return`${hex}${hh}`;
}
// Returns a version of the color that's legible AND pleasant as a fill/accent
// on the light background. Pure white / very light colours map to a soft,
// tasteful slate-blue (not a dead grey), so choosing "white" still yields a
// beautiful, visible timer. Mid/dark colours pass through unchanged.
function readable(hex){
  const rgb=hexToRgb(hex); if(!rgb) return "#FFFFFF";
  const lum=0.299*rgb[0]+0.587*rgb[1]+0.114*rgb[2];
  // Dark/mid background → white text reads best.
  if(lum<=170) return "#FFFFFF";
  // Light background: neutral white/grey → readable slate; coloured → deepen its hue.
  const mx=Math.max(...rgb), mn=Math.min(...rgb), sat=mx===0?0:(mx-mn)/mx;
  if(sat<0.08) return "#5A5470";
  return shadeHex(hex, -0.55);
}

// onCardColor — colour for a label that sits ON the page/card background (NOT on
// top of the colour itself). readable() is wrong there: a dark accent would come
// back white and vanish on a light card. Here we always return a tone of the
// accent that contrasts with the current surface: deepened in light mode, lifted
// in dark mode. Use this for time labels, meta text, etc. on cards.
function onCardColor(hex){
  if(!hexToRgb(hex)) return isDark()?"#C9C4D6":"#5A5470";
  return isDark()?shadeHex(hex,0.4):shadeHex(hex,-0.55);
}

// ── HEIC support ───────────────────────────────────────────────────────────
// iPhones often save photos as HEIC, which browsers can't draw to a canvas.
// We detect HEIC and convert it to JPEG using heic2any, loaded on demand from
// a CDN only when actually needed (normal JPEG/PNG uploads load nothing extra).
function isHeic(file){
  if(!file) return false;
  const ty=(file.type||"").toLowerCase();
  if(ty==="image/heic"||ty==="image/heif"||ty==="image/heic-sequence"||ty==="image/heif-sequence") return true;
  // Some browsers report an empty type for HEIC — fall back to the extension.
  const nm=(file.name||"").toLowerCase();
  return /\.(heic|heif)$/.test(nm);
}
// Content-based check: read the ISO-BMFF `ftyp` box brand from the first bytes.
// iPhone gallery files often arrive with an empty type and no extension, so the
// only reliable signal is the file's actual header.
async function sniffHeic(file){
  if(isHeic(file)) return true;
  try{
    const buf=await file.slice(0,32).arrayBuffer();
    const b=new Uint8Array(buf);
    // bytes 4..8 should be "ftyp"; the brand follows at 8..12 (+ compatible brands)
    const tag=String.fromCharCode(b[4],b[5],b[6],b[7]);
    if(tag!=="ftyp") return false;
    let s="";
    for(let i=8;i<b.length;i++){ const c=b[i]; s+=(c>=32&&c<127)?String.fromCharCode(c):" "; }
    s=s.toLowerCase();
    return /heic|heif|heix|hevc|mif1|msf1|heim|heis|hevm|hevs/.test(s);
  }catch(_){ return false; }
}
let _heic2anyPromise=null;
function loadHeic2any(){
  if(window.heic2any) return Promise.resolve(window.heic2any);
  if(_heic2anyPromise) return _heic2anyPromise;
  _heic2anyPromise=new Promise((resolve,reject)=>{
    const s=document.createElement("script");
    s.src="https://cdn.jsdelivr.net/npm/heic2any@0.0.4/dist/heic2any.min.js";
    s.async=true;
    const to=setTimeout(()=>{ _heic2anyPromise=null; reject(new Error("heic2any load timeout")); }, 8000);
    s.onload=()=>{ clearTimeout(to); resolve(window.heic2any); };
    s.onerror=()=>{ clearTimeout(to); _heic2anyPromise=null; reject(new Error("heic2any load failed")); };
    document.head.appendChild(s);
  });
  return _heic2anyPromise;
}
// Returns a Promise<Blob> of a JPEG, converting from HEIC if needed.
async function toDisplayableImage(file){
  if(!(await sniffHeic(file))) return file;
  const heic2any=await loadHeic2any();
  const out=await heic2any({blob:file, toType:"image/jpeg", quality:0.85});
  return Array.isArray(out)?out[0]:out;
}

